def _discover_legal_pages(
    raw_html_path: str | Path,
    source_url: str,
    output_path: Path,
    *,
    fallback_source_url: str | None = None,
) -> Path:
    """Find linked legal pages in the captured HTML without following click paths."""
    raw_html = Path(raw_html_path).read_bytes()
    document = lxml_html.fromstring(raw_html)
    categories = {
        "agb": ("agb", "allgemeine geschäftsbedingungen", "terms and conditions"),
        "datenschutz": ("datenschutz", "datenschutzerklärung", "privacy policy", "privacy"),
    }
    findings: dict[str, list[dict[str, Any]]] = {key: [] for key in categories}
    seen: dict[str, set[str]] = {key: set() for key in categories}
    source_host = (urlsplit(source_url).hostname or "").lower()
    for category, candidates in _known_site_legal_urls(source_url).items():
        for candidate in candidates:
            seen[category].add(candidate)
            findings[category].append({
                "label": "Bekannter öffentlicher Rechtstextpfad für diese Website",
                "url": candidate,
                "same_domain": True,
                "document_type": category,
                "source": "known_site_public_path",
            })
    if fallback_source_url is not None:
        for category, candidate in _fallback_legal_targets(fallback_source_url).items():
            if candidate in seen[category]:
                continue
            seen[category].add(candidate)
            findings[category].append({
                "label": "AGB" if category == "agb" else "Datenschutzerklärung",
                "url": candidate,
                "same_domain": True,
                "document_type": category,
                "source": "fallback_public_path",
            })
    for anchor in document.xpath("//a[@href]"):
        href = str(anchor.get("href") or "").strip()
        if not href or href.startswith(("#", "javascript:", "mailto:", "tel:")):
            continue
        label = " ".join(anchor.text_content().split()).strip()
        absolute_url = urljoin(source_url, href)
        parsed = urlsplit(absolute_url)
        if parsed.scheme not in {"http", "https"}:
            continue
        haystack = f"{label} {parsed.path}".casefold()
        for category, needles in categories.items():
            if any(needle in haystack for needle in needles) and absolute_url not in seen[category]:
                seen[category].add(absolute_url)
                findings[category].append({
                    "label": label or absolute_url,
                    "url": absolute_url,
                    "same_domain": (parsed.hostname or "").lower() == source_host,
                    "document_type": category,
                    "source": "anchor_in_saved_html",
                })
    # Shopify legal pages can exist at stable public endpoints without being linked in
    # the delivered start-page HTML. Probe only the two documented same-origin platform
    # paths, and only when ordinary link discovery found nothing for that category.
    if b"shopify" in raw_html.lower():
        origin = f"{urlsplit(source_url).scheme}://{urlsplit(source_url).netloc}"
        platform_paths = {
            "agb": "/policies/terms-of-service",
            "datenschutz": "/policies/privacy-policy",
        }
        for category, path in platform_paths.items():
            if findings[category]:
                continue
            candidate = urljoin(origin, path)
            findings[category].append({
                "label": "Bekannter öffentlicher Shopify-Rechtstextpfad",
                "url": candidate,
                "same_domain": True,
                "document_type": category,
                "source": "known_shopify_public_path",
            })
    payload = {
        "source_url": source_url,
        "method": (
            "Priorisierte bekannte öffentliche Website-Pfade und Linksuche im gespeicherten "
            "HTML; bei erkannter Shopify-Seite zusätzlich zwei Plattformpfade; keine "
            "Klickpfade aufgerufen. Bei einem Hauptseitenfehler wird je ein öffentlicher "
            "AGB- und Datenschutzpfad als dokumentiertes Ausweichziel berücksichtigt."
        ),
        "agb": findings["agb"][:20],
        "datenschutz": findings["datenschutz"][:20],
    }
    _write_json(output_path, payload)
    return output_path


def _legal_subpage_candidates(source_url: str) -> list[str]:
    parsed = urlsplit(source_url)
    origin = f"{parsed.scheme}://{parsed.netloc}"
